function SavingSchedule() {
  const [events, setEvents] = useState(plantEvents);
  return (
    <Panel className="h-140 w-full">
      <PanelBody>
        <Scheduler
          aria-label="Saved schedule"
          events={events}
          resources={PLANT_RESOURCES}
          defaultView="day"
          editable
          onEventChange={(change) =>
            // A save that takes a moment; Substation B is locked, so its changes fail and go back.
            new Promise<void>((resolve, reject) =>
              window.setTimeout(() => {
                if (change.event.resourceId === "substation")
                  return reject(new Error("Substation B is locked"));
                setEvents((current) => applyChange(current, change));
                resolve();
              }, 700),
            )
          }
        />
      </PanelBody>
    </Panel>
  );
}

function LoadingSchedule() {
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState<"month" | "week" | "agenda">("week");
  return (
    <div className="flex w-full flex-col gap-3">
      <div className="flex flex-wrap items-center gap-4">
        <Switch size="sm" checked={loading} onCheckedChange={setLoading} label="Loading" />
      </div>
      <Panel className="h-140 w-full">
        <PanelBody>
          <Scheduler
            aria-label="Loading schedule"
            events={loading ? [] : plantEvents()}
            loading={loading}
            view={view}
            onViewChange={(next) => setView(next as typeof view)}
            views={["month", "week", "agenda"]}
          />
        </PanelBody>
      </Panel>
    </div>
  );
}

// A change window fixed in UTC: each zone's grid shows it at its own wall-clock time.
const WINDOWS: SchedulerEvent[] = [
  {
    id: "w1",
    title: "Global change window",
    start: `${addDays(WEEK_START, 1)}T22:00:00Z`,
    end: `${addDays(WEEK_START, 2)}T01:00:00Z`,
    tone: 7,
    description: "22:00–01:00 UTC",
  },
  {
    id: "w2",
    title: "Firmware rollout",
    start: `${addDays(WEEK_START, 3)}T08:00:00Z`,
    end: `${addDays(WEEK_START, 3)}T10:00:00Z`,
    tone: 2,
  },
];
const ZONES = [
  { value: "Australia/Sydney", label: "Sydney" },
  { value: "Europe/Berlin", label: "Berlin" },
  { value: "America/New_York", label: "New York" },
];

function ZonedSchedule() {
  const [zone, setZone] = useState("Australia/Sydney");
  return (
    <div className="flex w-full flex-col gap-3">
      <Segmented
        size="sm"
        options={ZONES}
        value={zone}
        onValueChange={setZone}
        aria-label="Time zone"
      />
      <Panel className="h-140 w-full">
        <PanelBody>
          <Scheduler
            aria-label="Change windows"
            events={WINDOWS}
            timeZone={zone}
            scrollToTime="06:00"
          />
        </PanelBody>
      </Panel>
    </div>
  );
}

function CompactSchedule({ view }: { view: "week" | "month" }) {
  const [events, setEvents] = useState<PlantEvent[]>(plantEvents);
  return (
    <Panel className="h-160 w-full max-w-90">
      <PanelBody>
        <Scheduler
          aria-label={view === "week" ? "Narrow week" : "Narrow month"}
          events={events}
          resources={PLANT_RESOURCES}
          defaultView={view}
          views={["month", "week", "agenda"]}
          editable
          onEventChange={(change) => setEvents((current) => applyChange(current, change))}
        />
      </PanelBody>
    </Panel>
  );
}

